/*!40000 ALTER TABLE `comments` DISABLE KEYS */;
INSERT INTO `comments` VALUES (1,2,3,3,'Khởi đầu nhẹ nhàng nhưng cuốn hút quá! Thích suy nghĩ tự biết mình biết ta của nhân vật chính ghê.','2026-10-21 09:53:38','2026-10-22 04:53:38'),(2,2,3,5,'Góc nhìn người qua đường này đọc mới lạ thật sự, khác hẳn mấy truyện gồng mình làm bá chủ.','2026-10-21 21:53:38','2026-10-22 04:53:38'),(3,2,3,6,'Văn phong êm dịu, câu từ gãy gọn. Chấm theo dõi truyện ngay!','2026-10-22 02:53:38','2026-10-22 04:53:38'),(4,2,4,4,'Hỏi về đại hiệp khởi nghiệp nghe dễ thương xỉu, đúng chất người ngoài cuộc tò mò chuyện giang hồ.','2026-10-21 22:53:38','2026-10-22 04:53:38'),(5,2,4,7,'Cách đặt tên chương mộc mạc mà dí dỏm. Bút pháp rất tự nhiên.','2026-10-21 23:53:38','2026-10-22 04:53:38'),(6,2,31,5,'Đao kiếm dậy sóng bên ngoài mà quán trọ vẫn giữ được nét bình lặng, đoạn này tương phản cực hay!','2026-10-21 20:53:38','2026-10-22 04:53:38'),(7,2,31,3,'Tội nghiệp cây mộc hương của chưởng quầy bị chém rụng hoa, chi tiết đời thường đắt giá ghê.','2026-10-21 22:53:38','2026-10-22 04:53:38'),(8,2,32,6,'Lâm Thuấn xuất thủ ngầu đét luôn! Nhưng mình vẫn ủng hộ nữ chính né xa thị phi ra.','2026-10-21 20:53:38','2026-10-22 04:53:38'),(9,2,32,5,'Cảnh chiến đấu trên lầu cao miêu tả rất căng thẳng, đọc thót tim!','2026-10-22 03:53:38','2026-10-22 04:53:38'),(10,2,33,3,'Bát thuốc đắng và lời nhắc nhở... sự ấm áp kín đáo của người đầu bếp bắt đầu lộ rõ rồi nha!','2026-10-22 03:53:39','2026-10-22 04:53:39'),(11,2,33,4,'Đoạn này ngọt ngào tinh tế quá tác giả ơi, không cần nói yêu đương sến súa mà rung động ghê.','2026-10-22 00:53:39','2026-10-22 04:53:39'),(12,2,34,6,'Thời gian trôi như bóng câu qua cửa sổ... đọc đến đoạn này thấy thời gian nghiệt ngã quá.','2026-10-21 11:53:39','2026-10-22 04:53:39'),(13,2,34,7,'Năm tháng giang hồ qua đi, thứ còn lại duy nhất chính là người bên cạnh sẻ chia chén cơm ấm.','2026-10-21 16:53:39','2026-10-22 04:53:39'),(14,2,35,3,'Hồi kết tuyệt vời! Rất khâm phục tác giả đã giữ vững tôn chỉ từ chương đầu đến chương cuối.','2026-10-21 16:53:39','2026-10-22 04:53:39'),(15,2,35,5,'Một cái kết đẹp cho một câu chuyện ý nghĩa. Chúc mừng tác giả Thanh Phong Kiếm Khách!','2026-10-22 00:53:39','2026-10-22 04:53:39'),(16,2,35,6,'10 điểm không có nhưng! Truyện hay nhất mình đọc được dạo gần đây.','2026-10-22 00:53:39','2026-10-22 04:53:39');
/*!40000 ALTER TABLE `comments` ENABLE KEYS */;
UNLOCK TABLES;

