INSERT INTO `forum_categories` VALUES (1,'Thông Báo & Nội Quy','thong-bao-noi-quy','Quy tắc sinh hoạt cộng đồng, quyền lợi tác giả và thông báo chính thức từ Ban Quản Trị','📢',1),(2,'Thảo Luận & Cảm Nhận Truyện','thao-luan-truyen','Nơi phân tích cốt truyện, luận bàn nhân vật và chia sẻ góc nhìn văn học sâu sắc','💬',2),(3,'Góc Sáng Tác & Chia Sẻ Bút Lực','sang-tac-kinh-nghiem','Kinh nghiệm viết văn, cách xây dựng thế giới, thiết lập cao trào và gỡ rối mạch truyện','✍️',3),(4,'Tìm Truyện & Đề Cử Truyện Hay','de-cu-tim-truyen','Chia sẻ cảm nhận, review tác phẩm chất lượng và tìm kiếm truyện theo sở thích','🔍',4),(5,'Trà Quán Giang Hồ','tra-quan-giang-ho','Góc giao lưu thân mật giữa độc giả và tác giả, tản mạn cuộc sống và kết bạn bốn phương','☕',5),(6,'Hỏi Đáp & Góp Ý Diễn Đàn','hoi-dap-gop-y','Giải đáp thắc mắc cách sử dụng website, tiếp nhận ý kiến đóng góp xây dựng cộng đồng','💡',6);
/*!40000 ALTER TABLE `forum_categories` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `forum_posts`
--

DROP TABLE IF EXISTS `forum_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `forum_posts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL,
  `user_id` int NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `views` int DEFAULT '0',
  `is_pinned` tinyint(1) DEFAULT '0',
  `is_locked` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_forum_posts_cat` (`category_id`),
  KEY `idx_forum_posts_user` (`user_id`),
  KEY `idx_forum_posts_pinned` (`is_pinned`),
  CONSTRAINT `forum_posts_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `forum_categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `forum_posts_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `forum_posts`
--

LOCK TABLES `forum_posts` WRITE;
/*!40000 ALTER TABLE `forum_posts` DISABLE KEYS */;
INSERT INTO `forum_posts` VALUES (1,1,1,'[Nội Quy] Quy định chung khi tham gia thảo luận và sáng tác trên VNnettruyen','quy-dinh-chung-khi-tham-gia-thao-luan-va-sang-tac','Chào toàn thể thành viên và tác giả của VNnettruyen,\n\nĐể xây dựng một sân chơi văn học trực tuyến văn minh, chất lượng và tôn trọng bản quyền, Ban Quản Trị xin ban hành các quy định cơ bản:\n1. Tôn trọng bản quyền tác giả: Nghiêm cấm sao chép nội dung khi chưa có sự đồng ý của tác giả gốc.\n2. Ứng xử hòa nhã, lịch sự trong các chủ đề tranh luận. Không công kích cá nhân hay sử dụng ngôn từ phản cảm.\n3. Tác phẩm đăng tải phải tuân thủ chuẩn chính tả Tiếng Việt có dấu, trình bày rõ ràng từng chương hồi.\n\nChúc mọi người có những giờ phút thưởng thức văn học và sáng tác thật thăng hoa!',2451,1,0,'2026-10-21 15:39:20','2026-10-22 03:12:20'),(2,3,2,'[Sáng Tác] Làm thế nào để xây dựng một bối cảnh kiếm hiệp thuần Việt sống động?','lam-the-nao-de-xay-dung-boi-canh-kiem-hiep-thuan-viet','Chào các bạn đồng nghiệp sáng tác!\n\nRất nhiều bạn tâm sự với mình rằng khi viết kiếm hiệp, ngòi bút rất dễ bị cuốn theo các địa danh và phong cách Trung Hoa (như Thiếu Lâm, Võ Đang, Tung Sơn...). Để viết một tác phẩm mang đậm phong vị Việt Nam, mình xin chia sẻ 3 kinh nghiệm thực chiến:\n\n1. Dựa trên địa lý và lịch sử nước nhà: Sông Bạch Đằng, dãy Trường Sơn, đất Thăng Long ngàn năm, bến Đông Bộ Đầu hay rừng thiêng Phong Châu.\n2. Hệ thống vũ khí và võ học cổ truyền: Kiếm liễu, đao trường, côn nhị khúc, võ thế Nam Huỳnh Đạo hoặc võ Bình Định.\n3. Triết lý võ hiệp: Không chỉ là ân oán giang hồ, mà gắn liền với lòng yêu nước thương dân và nghĩa khí hào sảng của cha ông.\n\nCác bạn nghĩ sao về hướng đi này? Rất mong được nghe chia sẻ từ mọi người!',1821,1,0,'2026-10-21 15:39:20','2026-10-21 15:55:08'),(3,2,3,'[Cảm Nhận] \"Dây Tơ Hồng Nối Ngược\" - Nỗi buồn đẹp đẽ của những người từng thương','cam-nhan-day-to-hong-noi-nguoc-noi-buon-dep-de','Hôm qua vừa đọc xong hai chương đầu của \"Dây Tơ Hồng Nối Ngược\", mình thực sự bị ám ảnh bởi câu văn: \"Chưa từng có ai hỏi họ có mệt không? Có muốn buông tay hay không...\".\n\nTác giả miêu tả cơn mưa chiều Sài Gòn và sự tái ngộ giữa ngã tư đèn đỏ quá đỗi chân thực. Có những mối tình không phải vì hết thương mà dừng lại, mà là vì cả hai đã đi quá xa trên con đường trưởng thành của riêng mình. Có ai đang theo dõi bộ này không, vào đàm đạo với mình nhé!',951,0,0,'2026-10-21 15:39:20','2026-10-22 03:12:35'),(4,3,4,'[Kinh Nghiệm] Cách vượt qua giai đoạn cạn ý tưởng (Writer\'s Block) cho tác giả mới','cach-vuot-qua-giai-doan-can-y-tuong-writers-block','Chào mọi người, mình là Meovangnho!\n\nChắc hẳn ai từng cầm bút viết tiểu thuyết đều trải qua cảm giác ngồi hàng giờ trước màn hình máy tính trắng trơn mà không gõ nổi một chữ. Sau vài lần bị \"tắc bút\", mình rút ra vài mẹo nhỏ muốn chia sẻ cùng anh em:\n\n- Đừng cố hoàn hảo ngay từ bản nháp đầu tiên: Cứ viết ra hết những gì trong đầu, dù câu từ có lủng củng. Biên tập lại là việc của ngày hôm sau!\n- Đi dạo hoặc đổi không gian: Đôi khi ra bờ hồ ngồi uống cà phê ngắm dòng người qua lại lại nảy ra một tình huống đắt giá.\n- Đọc lại những chương đầu: Tìm lại cảm xúc và nhiệt huyết thuở ban đầu khi bạn nảy ra ý tưởng câu chuyện.\n\nAnh em tác giả có bí quyết nào nữa không, chỉ giáo cho mình với nha!',1240,1,0,'2026-10-21 15:39:20','2026-10-21 15:39:20'),(5,4,3,'[Đề Cử] Top 3 bộ truyện kiếm hiệp và dã sử Việt Nam đáng đọc nhất trên diễn đàn','top-3-bo-truyen-kiem-hiep-va-da-su-viet-nam-dang-doc-nhat','Dành cho những ai đang tìm kiếm tác phẩm chất lượng cuối tuần này:\n1. \"Huyền Khí Đại Việt\" - Cốt truyện hoành tráng, lồng ghép truyền thuyết dân tộc cực kỳ mượt mà.\n2. \"Thăng Long Kiếm Ảo\" - Những màn đấu kiếm được miêu tả sắc sảo, nghẹt thở.\n3. \"Bạch Hạc Dạ Hành\" - Phong cách trinh thám cổ trang kết hợp huyền bí rừng thiêng rất lôi cuốn.\n\nAnh em đọc xong nhớ để lại bình luận ủng hộ tác giả nhà mình nha!',1680,0,0,'2026-10-21 15:39:20','2026-10-21 15:39:20'),(6,5,4,'[Trà Quán] Sở thích viết lách vào lúc mấy giờ đêm của các bạn?','so-thich-viet-lach-vao-luc-may-gio-dem-cua-cac-ban','Mình nhận thấy khung giờ từ 23h đến 2h sáng là lúc tâm trí tĩnh lặng và chữ tuôn ra dạt dào nhất. Kèm theo một ly trà sen ấm hoặc tách cà phê sữa đá là đủ cho một đêm thăng hoa cùng nhân vật.\n\nCòn các bạn thì sao? Bạn thích viết vào sáng sớm tinh mơ hay đêm muộn yên tĩnh?',621,0,0,'2026-10-21 15:39:20','2026-10-22 03:31:59'),(7,2,2,'[Luận Bàn] Nghệ thuật xây dựng nhân vật phản diện: Đừng để kẻ ác chỉ đơn giản là điên cuồng','nghe-thuat-xay-dung-nhan-vat-phan-dien-co-chieu-sau','Một câu chuyện hay phụ thuộc rất nhiều vào độ sâu của nhân vật đối trọng với nhân vật chính. Một kẻ phản diện xuất sắc thường là người tin rằng hành động của mình là hoàn toàn đúng đắn dựa trên bi kịch quá khứ của họ.\n\nKhi độc giả vừa căm ghét tội ác nhưng lại vừa ngậm ngùi thấu hiểu cho nỗi đau của kẻ phản diện, đó là lúc ngòi bút của bạn đã chạm tới chiều sâu của cảm xúc con người.',1111,0,0,'2026-10-21 15:39:20','2026-10-21 16:36:20'),(8,6,3,'[Góp Ý] Đề xuất tính năng tự động lưu bản thảo khi đang sáng tác','de-xuat-tinh-nang-tu-dong-luu-ban-thao-khi-dang-sang-tac','Gửi Ban Quản Trị, nhiều khi đang viết truyện hăng say mà lỡ tay tắt trình duyệt hoặc mất điện đột ngột rất dễ mất nội dung vừa gõ. BQT có thể xem xét thêm tính năng auto-save vào bộ nhớ tạm trình duyệt (localStorage) để anh em tác giả yên tâm hơn được không ạ?',430,0,0,'2026-10-21 15:39:20','2026-10-21 15:39:20'),(9,2,3,'[Thảo Luận] Cảm nhận góc nhìn đặc biệt của \"Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp\" - Khi nhân vật phụ không muốn tranh đoạt thiên hạ','cam-nhan-goc-nhin-dac-biet-ta-chi-la-nhan-vat-nho-trong-truyen-kiem-hiep','Chào toàn thể anh em đạo hữu và các bạn đọc trên diễn đàn VNnettruyen!\n\nMấy ngày gần đây mình vừa đọc trọn vẹn bộ \"Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp\" của tác giả Thanh Phong Kiếm Khách và thực sự cảm thấy vô cùng tâm đắc.\n\nKhác hoàn toàn với mô-típ kiếm hiệp truyền thống thường thấy — nơi các nhân vật chính luôn khao khát bí tịch vô thượng, bước lên ngôi vị võ lâm minh chủ, danh chấn bát hoang — bộ truyện này lại dẫn dắt chúng ta đi theo bước chân của Lâm Thư Dao, một nữ đệ tử bình thường, người sớm nhận ra bản thân chỉ là một nhân vật nhỏ bé ven đường.\n\nNàng không màng hư danh, chỉ mong sau này cùng một chàng đầu bếp trầm mặc mở một quán trọ nhỏ dưới chân núi, sớm tối nấu cơm, pha trà, nhìn khách giang hồ qua lại. Cái cảm giác bình dị, an yên ấy giữa một thế giới đao kiếm tranh đấu gay gắt thực sự như một dòng suối mát lành tưới tắm tâm hồn người đọc.\n\nCác bạn ấn tượng nhất với tình tiết nào trong 7 chương truyện? Hãy cùng chia sẻ cảm nghĩ bên dưới nhé!',3840,1,0,'2026-10-20 15:53:38','2026-10-22 04:53:38'),(10,2,5,'[Phân Tích] Bối cảnh quán trọ giang hồ và hình tượng người đầu bếp ít nói trong truyện Kiếm Hiệp','phan-tich-boi-canh-quan-tro-giang-ho-va-nguoi-dau-bep-it-noi','Trong thế giới võ hiệp, quán trọ luôn là nơi ngọa hổ tàng long, nơi giao thoa của ân oán tình thù và những cuộc hội ngộ bất ngờ. \n\nNhưng trong tác phẩm của Thanh Phong Kiếm Khách, hình tượng người đầu bếp ít nói lại đại diện cho bến đỗ bình yên của cuộc đời. Một người đàn ông không dùng kiếm gươm, chỉ dùng đôi bàn tay mộc mạc nấu từng chén canh ấm, bảo bọc nữ chính qua những ngày giông bão của giang hồ.\n\nTheo các huynh đệ, đây có phải là mẫu hình nhân vật \"đại trí nhược ngu\" thường thấy ở những cao thủ ẩn dật không?',2950,0,0,'2026-10-21 16:53:38','2026-10-22 04:53:38'),(11,2,7,'[Luận Đàm] Triết lý \"Rửa tay gác kiếm\" - Liệu người trong giang hồ có thực sự tìm được bình yên trọn vẹn?','luan-dam-triet-ly-rua-tay-gac-kiem-trong-giang-ho','Cổ nhân có câu: \"Người tại giang hồ, thân bất do kỷ\". Đã bước chân vào chốn giang hồ, vướng vào vòng xoáy ân oán, thì liệu một chậu nước vàng rửa tay có đủ để gột sạch đao kiếm phân tranh?\n\nĐọc \"Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp\", ta thấy được nỗ lực của một con người bình thường muốn giữ trọn mạng sống và nhân tính. Nàng không cuốn mình vào đại thù của các môn phái lớn, mà chấp nhận làm người đứng bên ngoài lề.\n\nMời các tiền bối cùng đàm đạo: Để thực sự gác kiếm, điều quan trọng nhất là võ công tuyệt đỉnh hay là tâm thái buông bỏ của chính bản thân mình?',2420,0,0,'2026-10-20 08:53:38','2026-10-22 04:53:38'),(12,2,6,'[Cảm Nhận] Hồi kết chương 7 của \"Ta Chỉ Là Nhân Vật Nhỏ\": Nhẹ nhàng nhưng sâu lắng khôn nguôi','cam-nhan-hoi-ket-chuong-7-ta-chi-la-nhan-vat-nho','Đọc đến những dòng cuối cùng của Chương 7, mình thực sự nghẹn ngào. Khi các sư huynh lừng lẫy năm xưa người thì bỏ mình nơi chiến trận, kẻ thì cô độc trên đỉnh cao quyền lực, chỉ có nàng và quán trọ nhỏ nơi chân núi vẫn bình lặng đón từng tia nắng ban mai.\n\nMột kết thúc không phô trương thanh thế nhưng để lại dư âm rất dài. Cảm ơn tác giả đã mang đến một tác phẩm kiếm hiệp giàu tính nhân văn như vậy!',3120,0,0,'2026-10-20 08:53:38','2026-10-22 04:53:38'),(13,3,2,'[Kinh Nghiệm] Xây dựng nhân vật phụ có chiều sâu: Đừng biến họ thành \"công cụ làm nền\" vô hồn','kinh-nghiem-xay-dung-nhan-vat-phu-co-chieu-sau-trong-sang-tac','Chào các đồng nghiệp cầm bút trên diễn đàn!\n\nKhi chắp bút viết truyện kiếm hiệp, nhiều tác giả thường quá tập trung trau chuốt cho nhân vật chính mà quên mất rằng: thế giới truyện có sống động hay không phụ thuộc rất lớn vào dàn nhân vật phụ xung quanh.\n\nMột nhân vật phụ thành công cần:\n1. Động cơ sống riêng biệt, không xoay quanh nhân vật chính một cách vô lý.\n2. Nỗi sợ hãi và khát vọng đời thường (cơm áo gạo tiền, tình thân, sự an toàn).\n3. Cách nhìn nhận thế giới từ vị trí giai tầng của họ.\n\nTrong bộ \"Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp\", mình đã thử nghiệm đặt góc nhìn trọn vẹn vào một nhân vật phụ như thế, và nhận được rất nhiều phản hồi ấm áp từ quý độc giả. Rất vui được trao đổi kinh nghiệm cùng mọi người!',4560,1,0,'2026-10-20 14:53:38','2026-10-22 04:53:38'),(14,3,2,'[Kỹ Thuật Viết] Miêu tả các phân cảnh giao đấu kiếm pháp thuần Việt: Cách tạo nhịp điệu dồn dập','ky-thuat-mieu-ta-giao-dau-kiem-phap-thuan-viet','Nhiều bạn gửi thư hỏi mình về cách miêu tả các pha đấu kiếm sao cho vừa có chất võ học, vừa giữ được sự gãy gọn trong tiếng Việt.\n\nMột vài mẹo nhỏ mình đúc kết được:\n- Dùng nhiều động từ mạnh, câu văn ngắn ở cao trào giao chiêu.\n- Kết hợp âm thanh (tiếng kiếm rít, tiếng giáp rách, tiếng gió) để tăng tính chân thực.\n- Đừng lạm dụng tên chiêu thức quá dài dòng mà hãy miêu tả đường đi của mũi kiếm và phản xạ của đối thủ.\n\nCác bạn thường gặp khó khăn gì khi viết cảnh hành động? Chia sẻ ở đây để chúng ta cùng mổ xẻ nhé!',3890,0,0,'2026-10-21 17:53:38','2026-10-22 04:53:38'),(15,4,3,'[Đề Cử Cực Phẩm] \"Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp\" - Luồng gió mới lạ giữa rừng truyện tranh đấu','de-cu-cuc-pham-ta-chi-la-nhan-vat-nho-trong-truyen-kiem-hiep','Nếu bạn đã quá ngột ngạt với những bộ truyện nhân vật chính gánh vác sứ mệnh cứu vớt nhân gian, cả ngày chém giết thăng cấp... thì hãy thử đổi gió với \"Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp\".\n\nĐiểm cộng lớn nhất:\n- Văn phong mượt mà, giàu hình tượng, ngập tràn phong vị cổ trang.\n- Tâm lý nhân vật được khắc họa chân thật, gần gũi.\n- 7 chương trọn vẹn, không bôi vẽ tình tiết, đọc một lèo là xong nhưng nhớ mãi.\n\nĐánh giá: 9.5/10 - Rất đáng đọc trong tuần này!',4120,0,0,'2026-10-20 15:53:38','2026-10-22 04:53:38'),(16,4,6,'[Tìm Truyện] Xin giới thiệu các tác phẩm kiếm hiệp giang hồ có yếu tố ấm áp, điền viên / quán trọ bình dị','xin-gioi-thieu-truyen-kiem-hiep-am-ap-dien-vien-quan-tro','Chào mọi người! Sau khi cày xong bộ truyện của tác giả Thanh Phong, mình bị \"nghiện\" thể loại kiếm hiệp nhẹ nhàng như thế này luôn. \n\nCó huynh tỷ nào biết thêm bộ nào có bối cảnh mở quán trà, quán trọ hoặc nhân vật sống ẩn dật giữa giang hồ không ạ? Cho mình xin vài cái tên với!',2680,0,0,'2026-10-21 21:53:38','2026-10-22 04:53:38'),(17,5,7,'[Góc Đàm Đạo] Nếu được chọn một môn tuyệt kỹ võ công trong tiểu thuyết, các đạo hữu sẽ chọn môn nào?','neu-duoc-chon-mot-mon-tuyet-ky-vo-cong-ban-se-chon-mon-nao','Ngồi đàm đạo lúc rảnh rỗi cùng anh em giang hồ!\n\nGiả sử xuyên không vào thế giới võ hiệp, cho phép các đạo hữu chọn duy nhất một môn võ công trấn phái:\n1. Độc Cô Cửu Kiếm (Phá hết võ công thiên hạ)\n2. Lăng Ba Vi Bộ (Khinh công đệ nhất, chạy trốn vô song)\n3. Cửu Dương Thần Công (Nội lực hùng hậu vô biên)\n4. Dịch Cân Kinh (Dưỡng sinh trường thọ, nội công thuần chính)\n\nLão phu thì nghiêng về Lăng Ba Vi Bộ, vừa an toàn giữ mạng lại vừa tiêu dao tự tại. Các bạn chọn món nào?',4320,0,0,'2026-10-21 07:53:38','2026-10-22 04:53:38'),(18,5,2,'[Tản Mạn Quán Trọ] Chén rượu hâm nóng ngày mưa và những mẩu chuyện giang hồ nghe được từ khách qua đường','tan-man-quan-tro-chen-ruou-ngay-mua-va-chuyen-giang-ho','Hôm nay trời đổ mưa lớn, ngồi gõ lách cách từng dòng chữ mà thấy nhớ không khí quán trọ trong truyện quá. \n\nĐôi khi niềm vui của người viết không phải là vẽ nên những trận đại chiến kinh thiên động địa, mà chỉ là miêu tả tiếng củi tí tách trong lò, mùi thịt kho thơm phức lan tỏa khắp góc quán, và tiếng cười sảng khoái của những vị khách dừng chân trú mưa.\n\nChúc các bạn một buổi tối ấm áp bên trang sách!',2980,0,0,'2026-10-20 13:53:38','2026-10-22 04:53:38'),(19,5,4,'[Hỏi Vui] Bạn bắt đầu mê truyện kiếm hiệp từ tác phẩm nào và vì nhân vật nào?','ban-bat-dau-me-truyen-kiem-hiep-tu-tac-pham-nao','Mỗi người trong chúng ta chắc hẳn đều có một mối duyên ban đầu với dòng tiểu thuyết kiếm hiệp. \n\nVới mình thì đó là hình ảnh Lệnh Hồ Xung uống rượu hát vang giữa núi rừng. Còn các bạn thì sao? Kỷ niệm đầu tiên đưa bạn đến với thế giới kiếm hiệp là gì?',2310,0,0,'2026-10-20 17:53:38','2026-10-22 04:53:38'),(20,6,5,'[Góp Ý] Đề xuất tính năng đánh dấu chương đang đọc dở trên giao diện di động','gop-y-tinh-nang-danh-dau-chuong-dang-doc-do-tren-di-dong','Kính gửi Ban Quản Trị diễn đàn VNnettruyen,\n\nGiao diện đọc truyện hiện tại trên máy tính và điện thoại đều rất mượt mà và font chữ đọc rất êm mắt. Tuy nhiên, nếu có thêm nút \"Đánh dấu chương đang đọc\" tự động lưu lại vị trí cuộn trang để lần sau mở lại đọc tiếp thì tuyệt vời hơn nữa.\n\nRất mong BQT xem xét bổ sung tính năng tiện ích này!',1350,0,0,'2026-10-21 16:53:38','2026-10-22 04:53:38');
