INSERT INTO `genres` VALUES (1,'Truyện Ngắn','truyen-ngan','Các tác phẩm ngắn gọn, súc tích, giàu cảm xúc và triết lý nhân sinh đời thường'),(2,'Tình Cảm','tinh-cam','Chuyện tình yêu ngọt ngào, sâu lắng, duyên phận cuộc đời'),(3,'Dị Giới','di-gioi','Chuyển sinh sang thế giới phép thuật, ma thú và các chủng tộc kỳ lạ'),(4,'Xuyên Không','xuyen-khong','Vượt thời không về quá khứ hoặc đến thế giới khác bắt đầu cuộc đời mới'),(5,'Đô Thị','do-thi','Bối cảnh cuộc sống hiện đại, thương trường, y thuật và năng lực đô thành'),(6,'Kiếm Hiệp','kiem-hiep','Hành tẩu giang hồ, nghĩa khí võ hiệp và ân oán phân minh');
