LOCK TABLES `stories` WRITE;
/*!40000 ALTER TABLE `stories` DISABLE KEYS */;
INSERT INTO `stories` VALUES (1,'Xuyên Không Thành Mẹ Kế Ác Độc, Dẫn Con Chồng Đi Quậy Tung Hào Môn','xuyen-khong-thanh-me-ke-ac-doc-dan-con-chong-di-quay-tung-hao-mon',2,'Thanh Phong Kiếm Khách','Xuyên Không Thành Mẹ Kế Ác Độc, Dẫn Con Chồng Đi Quậy Tung Hào Môn','/public/uploads/covers/cover-1792636936254-865256749.jpg','completed',12522,1,'2026-10-21 15:39:20','2026-10-22 02:54:16'),(2,'Ta Chỉ Là Nhân Vật Nhỏ Trong Truyện Kiếm Hiệp','ta-chi-la-nhan-vat-nho-trong-truyen-kiem-hiep',2,'Thanh Phong Kiếm Khách','Ta luôn biết mình chỉ là một nhân vật nhỏ không quan trọng trong câu chuyện võ hiệp này. Khi lớn lên, ta sẽ gả cho một người đầu bếp trầm lặng, cùng hắn điều hành một quán trọ cũ nát bên chân núi, tiếp đón những khách lữ hành bốn phương. Dù không như các sư huynh đao kiếm tung hoành Cửu Châu lừng lẫy, nhưng ít nhất ta giữ được bình yên, tránh xa gió tanh mưa máu chốn giang hồ...','/public/uploads/covers/cover-1792637986391-931340746.jpg','completed',168503,1,'2026-10-21 15:39:20','2026-10-22 05:07:12'),(3,'Bạch Hạc Dạ Hành','bach-hac-da-hanh',2,'Thanh Phong Kiếm Khách','Đất Phong Châu ngút ngàn rừng thiêng nước độc, những vụ mất tích kỳ quái của các đoàn thương buôn đưa bộ đôi hình bộ phán quan vào vòng xoáy ma thuật cổ xưa.','/public/images/cover-3.jpg','completed',21450,1,'2026-10-21 15:39:20','2026-10-22 01:15:50'),(4,'Xuyên Thành Vợ Cũ Của Nam Chính Nhà Giàu','xuyen-thanh-vo-cu-cua-nam-chinh-nha-giau',3,'Minh Nguyệt Độc Giả','Tỉnh dậy, chồng của nguyên thân vứt cho cô một tờ giấy ly hôn.\r\n\r\nThư Nhan cầm lên nhìn, nhà thuộc về cô, xe thuộc về cô, tiền gửi ngân hàng thuộc về cô.\r\n\r\nSao! Con trai con gái cũng thuộc về cô\r\n\r\nKiếp trước còn là một cô gái trẻ, bây giờ làm mẹ?\r\n\r\nXích kê!\r\n\r\nNgôn ngữ mạng, từ đồng âm, ý nói sự phấn khích đáng yêu','/public/uploads/covers/cover-1792632760396-111008920.jpg','ongoing',19084,1,'2026-10-21 15:39:20','2026-10-22 01:43:32'),(6,'Bức Tường Màu Xanh','buc-tuong-mau-xanh',3,'Minh Nguyệt Độc Giả','Chiều nào tan trường, Linh cũng dắt đám học trò đi qua con ngõ nhỏ để về. Bức tường cũ kỹ cuối ngõ xi-măng bong tróc lốm đốm, màu xám lem nhem pha lẫn vết rêu xanh đen. Lũ trẻ lướt ngang như đi qua một thứ gì đó đã quá quen thuộc, không ai để ý.','/public/uploads/covers/cover-1792633733533-41322170.jpg','completed',8900,0,'2026-10-21 15:39:20','2026-10-22 01:50:05'),(8,'Từ Phế Vật Trở Thành Siêu Cấp Cao Thủ Đô Thị','tu-phe-vat-tro-thanh-sieu-cap-cao-thu-do-thi',1,'Cá Nhỏ','Lâm Dương là một chàng trai 20 tuổi, sở hữu y thuật xuất chúng được truyền thừa từ Thần Y Môn. Từ nhỏ sống trên núi cùng sư phụ và các sư tỷ, anh vừa có bản lĩnh phi thường vừa mang tính cách ham chơi, thích trêu chọc người khác. Sau khi được sư nương giao lại chức chưởng môn đời thứ 18, Lâm Dương bị buộc xuống núi để rèn luyện, phát triển Thần Y Môn và tìm người vợ đã được sư phụ định hôn từ khi anh còn nhỏ.\r\n\r\nTheo địa chỉ trên hôn thư, Lâm Dương đến Hàng Thành tìm vị hôn thê Nhan Khuynh Thành, nữ tổng tài xinh đẹp và tài giỏi của tập đoàn Nhan thị. Trùng hợp thay, cô chính là Chu Đồng, người từng tìm đến anh chữa bệnh trên núi. Tuy nhiên, khi Lâm Dương đến nhà họ Nhan, Khuynh Thành đã hôn mê nhiều ngày và các danh y đều bó tay. Dù tự tin có thể cứu chữa cho cô, anh lại bị Tưởng Xuyên, một kẻ theo đuổi Khuynh Thành, khinh thường và ngăn cản vì vẻ ngoài nghèo túng. Đúng lúc đó, Bách Lý Nhược Lam – tứ sư tỷ của Lâm Dương, đồng thời là vị thần y nổi tiếng Hắc Y Thánh Thủ – xuất hiện. Nhận ra tiểu sư đệ bị bắt nạt, cô lập tức ra mặt bảo vệ anh, khiến Tưởng Xuyên phải bẽ mặt.\r\n\r\nCâu chuyện mở ra hành trình xuống núi đầy thú vị của Lâm Dương, nơi anh dùng y thuật cao siêu, thân phận đặc biệt và sự trợ giúp của những sư tỷ tài giỏi để đối mặt với những kẻ coi thường mình, chữa bệnh cứu người và từng bước chinh phục cuộc sống bên ngoài.','/public/uploads/covers/cover-1792639377068-526311005.jpg','ongoing',4501,0,'2026-10-21 15:39:20','2026-10-22 03:23:47'),(9,'Tiếu Ngạo Giang Hồ','tieu-ngao-giang-ho',2,'Kim Dung','Tiếu Ngạo Giang Hồ là tác phẩm kiếm hiệp kinh điển đỉnh cao của đại văn hào Kim Dung. Tác phẩm xoay quanh cuộc đời của lãng tử Lệnh Hồ Xung phóng khoáng, trọng nghĩa khinh tài giữa chốn võ lâm đầy mưu mô tranh đoạt pho kiếm phổ Tịch Tà Kiếm Pháp. Giữa chánh tà bất phân, khúc Tiếu Ngạo Giang Hồ vang lên tượng trưng cho khát vọng tự do tuyệt đối của bậc trượng phu.','/public/images/cover-1.jpg','completed',128504,0,'2026-10-21 15:39:20','2026-10-22 04:53:38'),(10,'Nắng Trong Vườn','nang-trong-vuon',3,'Minh Nguyệt Độc Giả','Tản mạn về những khóm hoa ban tím, về con hẻm nhỏ thơm mùi hoa dạ lý hương và những phận người lặng lẽ đi qua mùa giông bão cuộc đời.','/public/uploads/covers/cover-1792634048274-175622848.jpg','completed',12450,0,'2026-10-21 15:39:20','2026-10-22 01:55:32'),(14,'Cưới Em Trước Cưng Chiều Em Sau','cuoi-em-truoc-cung-chieu-em-sau',4,'Mèo Vàng Nhỏ','Cuộc hôn nhân thương mại trị giá 30 tỷ giữa Tô Minh Nguyệt và tổng tài Tạ Nhiên ban đầu ngỡ chỉ là một giao dịch lạnh nhạt, bởi cô luôn đinh ninh anh vẫn tơ tưởng đến \"bạch nguyệt quang\" Lý Thiến. Dù ngoài mặt tính toán chi li và liên tục đấu khẩu, cả hai lại dần nảy sinh tình cảm qua những lần ghen tuông và hiểu lầm chồng chất. Đỉnh điểm là khi Minh Nguyệt cho rằng Tạ Nhiên bênh vực Lý Thiến, cô dứt khoát bỏ đi, sang Mỹ du học và quyết định làm mẹ đơn thân. Trải qua muôn vàn sóng gió, sự thật mới được phơi bày khi Tạ Nhiên gác lại mọi công việc bay sang Mỹ, tận tay chăm sóc cô vượt qua trầm cảm sau sinh và lạnh lùng cắt đứt hoàn toàn với Lý Thiến. Tình yêu chân thành và sự ân cần của anh cuối cùng đã gỡ bỏ mọi khúc mắc, đưa cuộc hôn nhân hợp đồng đi đến một cái kết viên mãn, ngọt ngào.','/public/uploads/covers/cover-1792639704416-294629590.jpg','completed',18200,0,'2026-10-22 03:28:24','2026-10-22 04:28:27');
/*!40000 ALTER TABLE `stories` ENABLE KEYS */;
UNLOCK TABLES;

